RSpec.describe DeliverInvoiceOperationJob, "remote commit redelivery" do
  # "a lost commit answer is redelivered and applies once;"
  it "redelivers a commit whose answer was lost and applies it on the fake exactly once" do
    fake = TimekeepingContract::FakeTimekeeping.new
    generation = TimekeepingOwnership.current.generation
    fake.generation = generation
    company_id = 61
    entry_id = fake.add_entry(company_id:, user_id: 1, project_id: 1, id: 7101).fetch("id")
    credential = fake.add_service(company_id:, name: "monolith", operations: %w[prepare commit abort mark_billed])
    minter = ->(company_id:, operation:) { credential }
    fake_client = TimekeepingContract::FakeClient.new(timekeeping: fake, relay: nil)
    client = Timekeeping::ReservationClient.new(http: fake_client, credential: minter)

    # Forwards every request to the fake, so the fake applies it, then loses
    # the answer to a commit.
    dropping_http = Object.new
    dropping_http.define_singleton_method(:call) do |method, path, headers: {}, body: nil|
      response = fake_client.call(method, path, headers:, body:)
      raise Timekeeping::ReservationClient::TransportError, "lost answer" if path.end_with?("/reservations/commit")

      response
    end
    dropping_client = Timekeeping::ReservationClient.new(http: dropping_http, credential: minter)

    operation_id = SecureRandom.uuid
    request = Invoices::ReservationRequest.new(
      company_id:, invoice_id: 20, operation_id:, generation:, disposition: "active", entries: [entry_id]
    )
    expect(client.prepare(request).state).to eq("prepared")
    InvoiceOperationIntent.create!(
      company_id:, invoice_id: 20, operation_id:, state: "committed",
      generation:, disposition: "active", desired_entry_ids: [entry_id]
    )
    row_id = InvoiceOperationOutboxItem.record!(
      kind: "commit", company_id:, invoice_id: 20, operation_id:, generation:,
      disposition: "active", desired_entry_ids: [entry_id]
    )

    described_class.perform_now(row_id, reservations: dropping_client)

    row = InvoiceOperationOutboxItem.find(row_id)
    expect(row.delivered_at).to be_nil
    expect(row.attempts).to eq(1)
    expect(fake.reservations_for(entry_id)).to eq([{ "invoice_id" => 20, "state" => "committed" }])

    described_class.perform_now(row_id, reservations: client)
    requests_after_redelivery = fake.requests.size
    described_class.perform_now(row_id, reservations: client)

    expect(row.reload.delivered_at).to be_present
    expect(fake.reservations_for(entry_id)).to eq([{ "invoice_id" => 20, "state" => "committed" }])
    expect(fake.entry_locked?(entry_id)).to be(true)
    expect(fake.requests.count { |sent| sent[:path].end_with?("/reservations/commit") }).to eq(2)
    # A delivered row is never sent again.
    expect(fake.requests.size).to eq(requests_after_redelivery)
  end
end

RSpec.describe DeliverInvoiceOperationJob, "remote abort after a lost prepare answer" do
  # "Abort delivery first replays the identical prepare (same operation_id and body), then aborts. A prepare whose answer was lost is then terminal, and a late copy cannot reserve."
  # "the fake applies prepare but the answer is dropped: the save fails, and after abort each entry's reservation state equals its state before the save;"
  it "aborts a prepare whose answer was lost by replaying the identical prepare, restoring every entry and leaving a late copy nothing to reserve" do
    fake = TimekeepingContract::FakeTimekeeping.new
    generation = TimekeepingOwnership.current.generation
    fake.generation = generation
    company_id = 62
    free_id = fake.add_entry(company_id:, user_id: 1, project_id: 1, id: 7201).fetch("id")
    held_id = fake.add_entry(company_id:, user_id: 1, project_id: 1, id: 7202).fetch("id")
    fake.add_reservation(entry_id: held_id, invoice_id: 21, state: "committed", disposition: "active")
    credential = fake.add_service(company_id:, name: "monolith", operations: %w[prepare commit abort mark_billed])
    minter = ->(company_id:, operation:) { credential }
    fake_client = TimekeepingContract::FakeClient.new(timekeeping: fake, relay: nil)
    client = Timekeeping::ReservationClient.new(http: fake_client, credential: minter)

    dropping_http = Object.new
    dropping_http.define_singleton_method(:call) do |method, path, headers: {}, body: nil|
      fake_client.call(method, path, headers:, body:)
      raise Timekeeping::ReservationClient::TransportError, "lost answer"
    end
    dropping_client = Timekeeping::ReservationClient.new(http: dropping_http, credential: minter)

    before_save = [free_id, held_id].index_with { |id| [fake.entry_locked?(id), fake.reservations_for(id)] }

    operation_id = SecureRandom.uuid
    request = Invoices::ReservationRequest.new(
      company_id:, invoice_id: 21, operation_id:, generation:, disposition: "active", entries: [free_id, held_id]
    )
    expect(dropping_client.prepare(request).state).to eq("retryable")
    # The fake applied the prepare even though its answer was lost.
    expect(fake.entry_locked?(free_id)).to be(true)

    InvoiceOperationIntent.create!(
      company_id:, invoice_id: 21, operation_id:, state: "failed",
      generation:, disposition: "active", desired_entry_ids: [free_id, held_id]
    )
    row_id = InvoiceOperationOutboxItem.record!(
      kind: "abort", company_id:, invoice_id: 21, operation_id:, generation:,
      disposition: "active", desired_entry_ids: [free_id, held_id]
    )

    described_class.perform_now(row_id, reservations: client)

    expect(InvoiceOperationOutboxItem.find(row_id).delivered_at).to be_present
    after_abort = [free_id, held_id].index_with { |id| [fake.entry_locked?(id), fake.reservations_for(id)] }
    expect(after_abort).to eq(before_save)

    prepares = fake.requests.select { |sent| sent[:path].end_with?("/reservations/prepare") }
    expect(prepares.size).to be >= 2
    expect(prepares.pluck(:body).uniq.size).to eq(1)
    expect(prepares.first[:body]["operation_id"]).to eq(operation_id)

    # A late copy of the original prepare reaches the fake after the abort.
    late = fake_client.call("POST", prepares.first[:path], headers: prepares.first[:headers], body: prepares.first[:body])
    expect(late.body["state"]).to eq("aborted") if late.status == 200
    expect(fake.entry_locked?(free_id)).to be(false)
    expect(fake.reservations_for(free_id)).to eq([])
  end
end

