        @dropped_path = dropped_path
        @dropped = false
      end

      def call(method, path, headers: {}, body: nil)
        response = @inner.call(method, path, headers:, body:)
        if path == @dropped_path && !@dropped
          @dropped = true
          raise Timekeeping::ReservationClient::TransportError, "commit answer lost"
        end
        response
