                      "disposition" => "active", "entries" => [entry_id] })
    InvoiceOperationIntent.create!(
      company_id:, invoice_id: 10, operation_id:, state: "committed",
      generation: 1, disposition: "active", desired_entry_ids: [entry_id]
    )
    row = InvoiceOperationOutboxItem.create!(
      company_id:, invoice_id: 10, operation_id:, kind: "commit",
      payload: { "company_id" => company_id, "invoice_id" => 10, "operation_id" => operation_id,
                 "generation" => 1, "disposition" => "active", "desired_entry_ids" => [entry_id] }
    )

    described_class.perform_now(row.id, reservations: client)

    expect(row.reload.delivered_at).to be_nil
    expect(row.attempts).to eq(1)

    described_class.perform_now(row.id, reservations: client)

    expect(row.reload.delivered_at).to be_present
    expect(fake.reservations_for(entry_id)).to eq([{ "invoice_id" => 10, "state" => "committed" }])
    expect(fake.entry_locked?(entry_id)).to be(true)
    expect(InvoiceOperationOutboxItem.where(company_id:, operation_id:).count).to eq(1)
  end
end

RSpec.describe DeliverInvoiceOperationJob, "timekeeping client reconciliation" do
  # "Decide the result from the remote state and the intent state through the contract's `save_reconciliation` table: remote committed with intent committed → existing_success; remote aborted with intent failed → save_failed; any other pair → retryable reconciliation_error. HTTP 200 alone is never success."
  it "a commit row whose intent is still pending stays undelivered even when Timekeeping commits the operation" do
    fake = TimekeepingContract::FakeTimekeeping.new
    company_id = fake.add_company
    user_id = fake.add_user(company_id:, role: "admin")
    project_id = fake.add_project(company_id:)
    entry_id = fake.add_entry(company_id:, user_id:, project_id:).fetch("id")
    credential = fake.add_service(company_id:, name: "monolith-invoices", operations: %w[prepare commit abort mark_billed])
    http = TimekeepingContract::FakeClient.new(timekeeping: fake, relay: nil)
    client = Timekeeping::ReservationClient.new(http:, credential: ->(company_id:, operation:) { credential })
    operation_id = SecureRandom.uuid
    fake.call("POST", "/v1/companies/#{company_id}/reservations/prepare",
              headers: { "Authorization" => "Bearer #{credential}" },
              body: { "invoice_id" => 10, "operation_id" => operation_id, "generation" => 1,
                      "disposition" => "active", "entries" => [entry_id] })
    InvoiceOperationIntent.create!(
      company_id:, invoice_id: 10, operation_id:, state: "pending",
      generation: 1, disposition: "active", desired_entry_ids: [entry_id]
    )
    row = InvoiceOperationOutboxItem.create!(
      company_id:, invoice_id: 10, operation_id:, kind: "commit",
      payload: { "company_id" => company_id, "invoice_id" => 10, "operation_id" => operation_id,
                 "generation" => 1, "disposition" => "active", "desired_entry_ids" => [entry_id] }
    )

    described_class.perform_now(row.id, reservations: client)

    expect(fake.reservations_for(entry_id)).to eq([{ "invoice_id" => 10, "state" => "committed" }])
    expect(row.reload.delivered_at).to be_nil
    expect(row.attempts).to eq(1)
  end
end

RSpec.describe DeliverInvoiceOperationJob, "timekeeping client stale generation" do
  # "`stale_generation` marks the row undeliverable with a log signal."
  it "an abort row answered stale_generation is marked undeliverable, never delivered, and stops counting attempts" do
    fake = TimekeepingContract::FakeTimekeeping.new
    company_id = fake.add_company
    user_id = fake.add_user(company_id:, role: "admin")
    project_id = fake.add_project(company_id:)
    entry_id = fake.add_entry(company_id:, user_id:, project_id:).fetch("id")
    credential = fake.add_service(company_id:, name: "monolith-invoices", operations: %w[prepare commit abort mark_billed])
    http = TimekeepingContract::FakeClient.new(timekeeping: fake, relay: nil)
    client = Timekeeping::ReservationClient.new(http:, credential: ->(company_id:, operation:) { credential })
    operation_id = SecureRandom.uuid
    # Ownership moved on after the save wrote its intent under generation 1.
    fake.generation = 2
    InvoiceOperationIntent.create!(
      company_id:, invoice_id: 10, operation_id:, state: "failed",
      generation: 1, disposition: "active", desired_entry_ids: [entry_id]
    )
    row = InvoiceOperationOutboxItem.create!(
      company_id:, invoice_id: 10, operation_id:, kind: "abort",
      payload: { "company_id" => company_id, "invoice_id" => 10, "operation_id" => operation_id,
                 "generation" => 1, "disposition" => "active", "desired_entry_ids" => [entry_id] }
    )
    allow(Rails.logger).to receive(:warn).and_call_original

    described_class.perform_now(row.id, reservations: client)
    described_class.perform_now(row.id, reservations: client)

    row.reload
    expect(row.undeliverable_at).to be_present
    expect(row.delivered_at).to be_nil
    expect(row.attempts).to eq(0)
    expect(Rails.logger).to have_received(:warn).with(a_string_including(operation_id)).once
    expect(Rails.logger).not_to have_received(:warn).with(a_string_including(credential))
  end
end

RSpec.describe DeliverInvoiceOperationJob, "timekeeping client delivery through reconciliation" do
  let(:reconcile_fake) do
    TimekeepingContract::FakeTimekeeping.new.tap { |fake| fake.generation = TimekeepingOwnership.current.generation }
  end
  let(:reconcile_company_id) { 614 }
  let(:reconcile_client) do
    credential = reconcile_fake.add_service(company_id: reconcile_company_id, name: "monolith-invoices",
                                            operations: %w[prepare commit abort mark_billed])
    Timekeeping::ReservationClient.new(
      http: TimekeepingContract::FakeClient.new(timekeeping: reconcile_fake, relay: nil),
      credential: ->(company_id:, operation:) { credential }
    )
  end

  def reconcile_row(kind:, intent_state:, operation_id:, entry_ids:)
    generation = TimekeepingOwnership.current.generation
    InvoiceOperationIntent.create!(
      company_id: reconcile_company_id, invoice_id: 30, operation_id:, state: intent_state,
      generation:, disposition: "active", desired_entry_ids: entry_ids
    )
    InvoiceOperationOutboxItem.record!(
      kind:, company_id: reconcile_company_id, invoice_id: 30, operation_id:, generation:,
      disposition: "active", desired_entry_ids: entry_ids
    )
  end

  def reconcile_request(operation_id, entry_ids, invoice_id: 30)
    Invoices::ReservationRequest.new(
      company_id: reconcile_company_id, invoice_id:, operation_id:,
      generation: TimekeepingOwnership.current.generation, disposition: "active", entries: entry_ids
    )
  end

  it "keeps a commit row undelivered when Timekeeping already aborted the operation and answers the commit with 200" do
    entry_id = reconcile_fake.add_entry(company_id: reconcile_company_id, user_id: 1, project_id: 2).fetch("id")
    operation_id = SecureRandom.uuid
    expect(reconcile_client.prepare(reconcile_request(operation_id, [entry_id])).state).to eq("prepared")
    expect(reconcile_client.abort(reconcile_request(operation_id, [entry_id])).state).to eq("aborted")
    row_id = reconcile_row(kind: "commit", intent_state: "committed", operation_id:, entry_ids: [entry_id])

    described_class.perform_now(row_id, reservations: reconcile_client)

    row = InvoiceOperationOutboxItem.find(row_id)
    expect(row.delivered_at).to be_nil
    expect(row.attempts).to eq(1)
    expect(reconcile_fake.entry_locked?(entry_id)).to be(false)
  end

  it "delivers an abort row whose prepare replay was refused once the conflicting entry is released" do
    entry_id = reconcile_fake.add_entry(company_id: reconcile_company_id, user_id: 1, project_id: 2).fetch("id")
    holder = reconcile_request(SecureRandom.uuid, [entry_id], invoice_id: 31)
    expect(reconcile_client.prepare(holder).state).to eq("prepared")
    operation_id = SecureRandom.uuid
    row_id = reconcile_row(kind: "abort", intent_state: "failed", operation_id:, entry_ids: [entry_id])

    described_class.perform_now(row_id, reservations: reconcile_client)

    row = InvoiceOperationOutboxItem.find(row_id)
    expect(row.delivered_at).to be_nil
    expect(row.attempts).to eq(1)

    expect(reconcile_client.abort(holder).state).to eq("aborted")
    described_class.perform_now(row_id, reservations: reconcile_client)

    expect(row.reload.delivered_at).to be_present
    expect(reconcile_fake.requests.count { |sent| sent[:path].end_with?("/reservations/abort") }).to eq(2)
    expect(reconcile_fake.entry_locked?(entry_id)).to be(false)
    expect(reconcile_fake.reservations_for(entry_id)).to eq([])
  end
end
